const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

// chunk splitting everywhere, incl. CR|LF and escape quotes
function splitParse(text, size, opts) {
  const p = createParser(opts);
  const out = [];
  for (let i = 0; i < text.length; i += size) out.push(...p.push(text.slice(i, i + size)));
  out.push(...p.end());
  return out;
}
const samples = [
  'a,b\r\nc,d\n',
  '\"x\"\"y\",z\r\n\"q\r\nr\",s',
  '\r\r\n\n',
  'a,\"b\rc\",d\re',
];
for (const s of samples) {
  const whole = splitParse(s, Infinity);
  for (let size = 1; size <= 3; size++)
    assert.deepEqual(splitParse(s, size), whole, JSON.stringify(s) + ' size ' + size);
}

// basics
assert.deepEqual(parse(''), []);
assert.deepEqual(parse('\n'), [['']]);
assert.deepEqual(parse('\n\n'), [[''], ['']]);
assert.deepEqual(parse('a\n'), [['a']]);
assert.deepEqual(parse('a\r\nb\rc'), [['a'], ['b'], ['c']]);
assert.deepEqual(parse('﻿a,b'), [['a','b']]); // BOM stripped
assert.deepEqual(parse('a﻿b'), [['a﻿b']]); // inner BOM literal
assert.deepEqual(parse('a\"b'), [['a\"b']]); // literal quote in unquoted field
