  let fields = [];
  let recordStarted = false; // current record holds data not yet emitted
  let line = 1;
  let prevCR = false; // previous char was '\r' (CRLF counts once, even across chunks)
  let skipLF = false; // an outside-quote CR ended a record; swallow a following LF
  let atStart = true; // no character of input seen yet (BOM stripping)
  let ended = false;

  function push(chunk) {
    if (ended) throw new Error('push after end');
    if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
