  // 3 = just saw '"' inside a quoted field (escape or closing quote).
  let state = 0;
  let field = '';
  let fields = [];
  let recordStarted = false; // current record holds data not yet emitted
  let line = 1;
  let prevCR = false; // previous char was '\r' (CRLF counts once, even across chunks)
  let skipLF = false; // an outside-quote CR ended a record; swallow a following LF
  let atStart = true; // no character of input seen yet (BOM stripping)
  let ended = false;

  function push(chunk) {
    if (ended) throw new Error('push after end');
    if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
    const records = [];
    const emit = () => {
      records.push(fields);
      fields = [];
      field = '';
      recordStarted = false;
    };
    for (const c of chunk) {
      if (c === '\r') line++;
      else if (c === '\n' && !prevCR) line++;
      prevCR = c === '\r';

      if (atStart) {
        atStart = false;
        if (c === '\uFEFF') continue; // strip one leading BOM
      }
      if (skipLF) {
        skipLF = false;
        if (c === '\n') continue;
      }

      if (state === 0) {
        recordStarted = true;
        if (c === delimiter) {
          fields.push('');
        } else if (c === '"') {
          state = 2;
        } else if (c === '\r') {
          fields.push('');
          emit();
          skipLF = true;
        } else if (c === '\n') {
          fields.push('');
          emit();
        } else {
          field = c;
          state = 1;
        }
      } else if (state === 1) {
        if (c === delimiter) {
          fields.push(field);
          field = '';
          state = 0;
        } else if (c === '\r') {
          fields.push(field);
          emit();
          skipLF = true;
          state = 0;
        } else if (c === '\n') {
          fields.push(field);
          emit();
          state = 0;
        } else {
