const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');

function splitParse(text, size, opts) {
  const p = createParser(opts);
  const out = [];
  for (let i = 0; i < text.length; i += size) out.push(...p.push(text.slice(i, i + size)));
  out.push(...p.end());
  return out;
}
const samples = [
  'a,b\r\nc,d\n',
  '\"x\"\"y\",z\r\n\"q\r\nr\",s',
  '\r\r\n\n',
  'a,\"b\rc\",d\re',
  '﻿\"﻿lit\",x\r\n\ny', // BOM strip + literal BOM in quotes
];
for (const s of samples) {
  const whole = splitParse(s, Infinity);
  for (let size = 1; size <= 4; size++)
    assert.deepEqual(splitParse(s, size), whole, JSON.stringify(s) + ' size ' + size);
}

assert.deepEqual(parse(''), []);
assert.deepEqual(parse('\n'), [['']]);
assert.deepEqual(parse('\n\n'), [[''], ['']]);
assert.deepEqual(parse('a\n'), [['a']]);
assert.deepEqual(parse('a\r\nb\rc'), [['a'], ['b'], ['c']]);
assert.deepEqual(parse('a\rb\rc\n'), [['a'], ['b'], ['c']]);
assert.deepEqual(parse('﻿a,b'), [['a','b']]);
assert.deepEqual(parse('a\"b'), [['a\"b']]);
assert.deepEqual(parse('\"\"'), [['']]);
assert.deepEqual(parse(','), [['','']]);
assert.deepEqual(parse('\"a\"'), [['a']]);
assert.deepEqual(parse('a,b\n\n'), [['a','b'], ['']]);

const p = createParser();
assert.deepEqual(p.push(''), []);
assert.deepEqual(p.push('x,\"a'), []);
assert.deepEqual(p.push('b\"'), []);
assert.deepEqual(p.push(',y\nz,'), [['x','ab','y']]);
assert.deepEqual(p.end(), [['z','']]);
assert.deepEqual(p.end(), []);
assert.throws(() => p.push(''), /^Error/);
assert.throws(() => p.push(1), TypeError);
const p2 = createParser();
assert.throws(() => p2.push(42), TypeError);

assert.deepEqual(parse('a;b\nc;d', { delimiter: ';' }), [['a','b'],['c','d']]);
for (const d of ['', 'ab', '\"', '\r', '\n', 5, null]) assert.throws(() => createParser({ delimiter: d }), RangeError);

assert.throws(() => parse('a\n\"x\"y'), /line 2/);
assert.throws(() => parse('\"a\nb\" c'), /line 2/);
assert.throws(() => parse('\"a\r\nb\" c'), /line 2/);
assert.throws(() => parse('\"a\r\nb\r c'), /line 3/);
assert.throws(() => parse('\"a\nb\" '), SyntaxError);
assert.throws(() => parse('ok\r\n\"unterm'), /line 2/);
const q = createParser();
q.push('\"a\r');
assert.throws(() => { q.push('\nb'); q.end(); }, /line 2/);

assert.deepEqual(parse('a,a\n1,2\n3', { header: true }), [{ a: '1', a_2: '2' }, { a: '3', a_2: '' }]);
assert.deepEqual(parse('', { header: true }), []);

// parser independence
const a1 = createParser(), a2 = createParser();
a1.push('1\n'); a2.push('2,');
assert.deepEqual(a1.end(), []); assert.deepEqual(a2.end(), [['2','']]);
console.log('all edge-case checks passed');
"

